SELECT 100.0 * SUM(CASE WHEN (SELECT COUNT(*) FROM atom a WHERE a.molecule_id = m.molecule_id AND lower(a.element) = 'cl') > 0 THEN 1 ELSE 0 END) / COUNT(*) AS percentage
FROM molecule m
WHERE m.label = '+';

